// ── Reveal ────────────────────────────────────────────────────────
function Reveal({ children, delay = 0, className = "" }) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) { setVisible(true); obs.disconnect(); } },
      { threshold: 0.1 }
    );
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);
  return (
    <div ref={ref} className={className} style={{
      opacity: visible ? 1 : 0,
      transform: visible ? "translateY(0)" : "translateY(28px)",
      transition: `opacity .8s ease ${delay}s, transform .8s ease ${delay}s`,
    }}>{children}</div>
  );
}

// ── Primitives ────────────────────────────────────────────────────
function Divider() {
  return <div style={{ width:"100%", height:1, background:"linear-gradient(to right,transparent,rgba(201,168,76,.3),transparent)" }} />;
}

function Eyebrow({ children, center = false }) {
  return (
    <div style={{ fontSize:".68rem", letterSpacing:".28em", textTransform:"uppercase",
      color:s.gold, display:"flex", alignItems:"center", gap:"1rem",
      marginBottom:"1.4rem", justifyContent: center ? "center" : "flex-start" }}>
      {!center && <span style={{ display:"inline-block", width:30, height:1, background:s.gold }} />}
      {children}
    </div>
  );
}

function H2({ children, style={} }) {
  return (
    <h2 style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:"clamp(2.4rem,5vw,4rem)",
      fontWeight:300, lineHeight:1.1, color:s.cream, marginBottom:"1.5rem", ...style }}>
      {children}
    </h2>
  );
}

function BtnGold({ children, onClick }) {
  const [h, setH] = useState(false);
  return (
    <button onClick={onClick} onMouseEnter={()=>setH(true)} onMouseLeave={()=>setH(false)}
      style={{ background: h ? s.goldLight : s.gold, border:"none", padding:"1.1rem 2.8rem",
        fontFamily:"'Jost', sans-serif", fontSize:".78rem", fontWeight:500,
        letterSpacing:".18em", textTransform:"uppercase", color:s.black, cursor:"pointer",
        transform: h ? "translateY(-2px)" : "none", transition:"background .3s,transform .2s" }}>
      {children}
    </button>
  );
}

function BtnOutline({ children, onClick }) {
  const [h, setH] = useState(false);
  return (
    <button onClick={onClick} onMouseEnter={()=>setH(true)} onMouseLeave={()=>setH(false)}
      style={{ background:"transparent", border:`1px solid ${h ? s.gold : "rgba(245,240,232,.25)"}`,
        padding:"1.1rem 2.8rem", fontFamily:"'Jost', sans-serif", fontSize:".78rem", fontWeight:400,
        letterSpacing:".18em", textTransform:"uppercase", color: h ? s.gold : "rgba(245,240,232,.6)",
        cursor:"pointer", transition:"border-color .3s,color .3s" }}>
      {children}
    </button>
  );
}

